/* 「閲覧のみ」のスタッフには開かせない編集専用の画面。
   ここに挙げた画面以外（大会の中のタブ類など）は今までどおり閲覧できる。 */
const EDIT_ONLY_VIEWS = new Set(["new","settings","roster","club","sched","lineup","official","match"]);
function viewViewerBlocked(){
  return topbar({ title:"閲覧のみのアカウント", back:"go('home')" })
  + `<div class="screen"><div class="empty">この画面は「大会管理者」だけが使えます。<br>あなたは「閲覧のみ」の権限で招待されています。</div></div>`;
}
function render(){
  const blockedForViewer = state.user && state.user.role==="viewer" && EDIT_ONLY_VIEWS.has(state.view);
  const v = blockedForViewer ? viewViewerBlocked : ({
    home:viewHome, login:viewLogin, new:viewNew,
    t:viewTournament, match:viewMatch, teams:viewTeams, settings:viewSettings,
    roster:viewRoster, club:viewClub, official:viewOfficial, officialPublic:viewOfficialPublic, lineup:viewLineup, sched:viewSchedule,
    teamPublic:viewTeamPublic,
    entry:viewEntry, entrylinks:viewEntryLinks,
    clubentry:viewClubEntry, clubentrylinks:viewClubEntryLinks,
    terms:viewTerms,
  }[state.view] || viewHome);
  const y = window.scrollY;
  // PC用サイドバー表示（980px以上）では画面全体ではなく.tmainの中がスクロールする＝
  // その場合はwindow.scrollYが常に0のままなので、.tmain自身のスクロール位置も別途保持する
  const tmainOld = document.querySelector(".tmain");
  const ty = tmainOld ? tmainOld.scrollTop : 0;
  // 大会内タブ（大会概要〜出場記録）はスマホ幅だと横スクロールする帯。押すたびに先頭へ戻ると
  // 押した場所ごと見失うので、こちらは画面の切り替えに関係なく常に横位置を保つ
  const tabsOld = document.querySelector(".tabs");
  const tx = tabsOld ? tabsOld.scrollLeft : 0;
  const changed = state.view!==_lastView || (state.view==="t" && state.tab!==_lastTab);
  $("#app").innerHTML = v();
  // トーナメント表があれば櫓レイアウト＋接続線を描く（DOM確定後）
  if(document.getElementById("koCanvas")){
    requestAnimationFrame(()=>{ layoutBracket(); drawLinks(); });
  }
  // 画面（やタブ）が変わったときだけ先頭へ。同じ画面の描き直しは位置を保つ
  const tmainNew = document.querySelector(".tmain");
  if(changed){ window.scrollTo(0,0); if(tmainNew) tmainNew.scrollTop = 0; }
  else{ window.scrollTo(0,y); if(tmainNew) tmainNew.scrollTop = ty; }
  const tabsNew = document.querySelector(".tabs");
  if(tabsNew) tabsNew.scrollLeft = tx;
  _lastView = state.view; _lastTab = state.tab;
}
window.addEventListener("resize", ()=>{ if(document.getElementById("koCanvas")){ layoutBracket(); drawLinks(); } });

/* ゴールドのトロフィー（ブランドマーク） */
const TROPHY = `<svg class="mark" viewBox="0 0 24 24" fill="none" aria-hidden="true">
  <path d="M6.5 3.5h11V7a5.5 5.5 0 0 1-11 0V3.5Z" fill="#D4AF37"/>
  <path d="M6.6 4.6H4.4a1 1 0 0 0-1 1V7a3.2 3.2 0 0 0 3.2 3.2" stroke="#D4AF37" stroke-width="1.5"/>
  <path d="M17.4 4.6h2.2a1 1 0 0 1 1 1V7a3.2 3.2 0 0 1-3.2 3.2" stroke="#D4AF37" stroke-width="1.5"/>
  <path d="M11 12.4h2v2.6h-2z" fill="#D4AF37"/>
  <path d="M8 19l1-3.2h6L16 19Z" fill="#D4AF37"/>
  <rect x="7.2" y="18.6" width="9.6" height="2" rx="1" fill="#D4AF37"/>
</svg>`;

function topbar({title, sub, back, act}){
  return `<div class="topbar">
    ${back ? `<button class="back" onclick="${back}">‹ 戻る</button>` : TROPHY}
    <div class="ttl"><h1>${esc(title)}</h1>${sub?`<div class="sub">${esc(sub)}</div>`:""}</div>
    ${act || ""}
  </div>`;
}

