async function createTournament(){
  if(!state.user) return toast("先にログインしてください");
  const names = draft.teams.split("\n").map(s=>s.trim()).filter(Boolean);
  if(!draft.name.trim()) return toast("大会名を入れてください");
  if(names.length < 2)   return toast("チームを2つ以上入れてください");

  const f = FORMATS[draft.format];
  const tid = uid();
  // ブロック（部・組）を確定。空名は「1部」「2部」…で補う
  const blocks = f.hasLeague
    ? draft.blocks.map((nm,i)=>({ id:uid(), name:(nm||"").trim() || `${i+1}部` }))
    : [];
  const blockIds = blocks.map(b=>b.id);
  // ブロックごとの勝ち上がり数（作成画面では並び順の番号で持っている）を id に付け替える
  const advanceBy = {};
  blocks.forEach((b,i)=>{ const v = draft.advanceByIdx[i]; if(v!=null && v!=="") advanceBy[b.id] = Math.max(0,num(v)); });
  const advOf = id => advanceBy[id] != null ? advanceBy[id] : Math.max(0,num(draft.advance));
  const wildcards = (draft.wildcards||[]).filter(w=>num(w.rank)>0 && num(w.count)>0)
                                         .map(w=>({ rank:num(w.rank), count:num(w.count) }));
  const wcTotal = wildcards.reduce((a,w)=>a+w.count, 0);
  // トーナメント（櫓）の一覧。1つめは既定名、以降は作成画面で付けた名前
  const brackets = f.hasKO
    ? [{ id:KO_MAIN, name: draft.format==="league_ko" ? "決勝トーナメント" : "トーナメント" }]
        .concat((draft.bracketNames||[]).map((nm,i)=>({ id:uid(), name:(nm||"").trim() || `${i+2}位トーナメント` })))
    : [];
  const pow2 = n => Math.pow(2, Math.max(1, Math.ceil(Math.log2(Math.max(2, n)))));
  const qualifiers = blockIds.reduce((a,id)=>a+advOf(id), 0) + wcTotal;
  const koSize = draft.format==="ko"
      ? Math.max(draft.koSize, pow2(names.length))        // チームが枠より多ければ枠を広げる
      : pow2(qualifiers);

  const t = {
    id:tid, org_id:state.user.id, name:draft.name.trim(),
    sport:draft.sport, format:draft.format,
    settings:{ win:3, draw:1, lose:0, host:draft.host.trim(),
               gradeCat:draft.gradeCat||null, scope:draft.scope||null,
               promote:draft.promote||0, relegate:draft.relegate||0,
               overview:{...draft.overview},
               date:draft.dateStart, dateStart:draft.dateStart, dateEnd:draft.dateEnd,
               blocks, advance:draft.advance, advanceBy, wildcards, wcRule:draft.wcRule||"total",
               brackets, koSize, thirdPlace:draft.thirdPlace, doubleRound:!!draft.doubleRound,
               venues:[], duration:20 },
    created_at:new Date().toISOString(),
  };

  // チーム。リーグは指定ブロックへ手動振り分け（未指定は先頭）。台帳のは選手も入れる
  const teams = names.map((name,i)=>{
    const club = draft.picked.find(p=>p.name===name);
    const clubRec = club ? clubById(club.id) : null;
    const bIdx = blocks.length ? (draft.assign[name] ?? 0) : null;
    return {
      id:uid(), tournament_id:tid, org_id:state.user.id, name,
      grp: blocks.length ? (blocks[Math.min(bIdx, blocks.length-1)]?.id || blocks[0].id) : null,
      seed:i+1, sort_order:i, club_id: club?.id || null,
      ...clubProfileFields(clubRec),
      // 同じ台帳から複数チーム(A/B/C…)に分けたときは自動で選手を入れない（台帳から選んで手分けしてもらう）
      players: (club && !club.split) ? membersOf(club.id).map(m=>({
        id:m.id, memberId:m.id, no:m.no, name:m.name, pos:m.pos, grade:m.grade })) : [],
    };
  });

  // 対戦カード
  let matches = [];
  if(f.hasLeague) matches = matches.concat(buildLeagueMatches(tid, teams, blockIds, !!draft.doubleRound));
  if(f.hasKO){
    const items = draft.format==="ko"
        ? []                                              // トーナメントのみ：空櫓スタート（作成後に各枠へ配置）
        : qualifierSlots(blockIds, advOf, wildcards);     // 予選つき：1部1位…＋ワイルドカードの枠
    matches = matches.concat(buildKOMatches(tid, koSize, distributePairs(items, koSize), draft.thirdPlace, KO_MAIN));
    // 2つめ以降のトーナメントは空の櫓（準決勝2＋決勝1）を用意し、中身はあとから組む
    brackets.slice(1).forEach(b=> matches.push(...emptyBracketSkeleton(tid, b.id)));
  }
  matches.forEach(m=> m.org_id = state.user.id);

  try{
    await DB.upsert("gn_tournaments", t);
    await DB.upsert("gn_teams", teams);
    await DB.upsert("gn_matches", matches);
  }catch(e){ console.error(e); return toast("保存できませんでした: "+(e.message||e)); }

  const needsPick = teams.filter(x=>x.club_id && !x.players.length).length;

  Object.assign(draft, { name:"", host:"", dateStart:"", dateEnd:"", teams:"", picked:[], assign:{}, blocks:["1部"],
                         advanceByIdx:{}, wildcards:[], wcRule:"total", bracketNames:[],
                         gradeCat:"", scope:"", promote:0, relegate:0, overview:{...OVERVIEW_DEFAULT} });
  await reloadList();
  openTournament(tid);
  if(needsPick) toast(`${needsPick}チームぶん、まだ選手が入っていません。「チーム・選手」から「台帳から入れる」で選んでください`);
}

/* ---------- 大会画面 ---------- */
/* 大会内タブの一覧（サイドバー・横タブ両方で共用） */
function tournamentTabs(t, cfg){
  const f = FORMATS[t.format];
  return [
    ["overview","大会概要"],
    ["notice","お知らせ"],
    ["schedule","日程・結果"],
    ...(f.hasLeague ? [["table","順位表"],["matrix","戦績表"]] : []),
    ...(f.hasKO ? [["bracket","トーナメント表"]] : []),
    ...(sportOf(t).scorers ? [["scorers","得点ランキング"]] : []),
    ...(sportOf(t).scorers ? [["assists","アシストランキング"]] : []),
    ["appear","出場記録"],
    // 警告・退場／チーム・選手 は管理者だけ（保護者・一般には出さない）
    ...(canEdit() && sportOf(t).cards ? [["cards","警告・退場"]] : []),
    ...(canEdit() ? [["team","チーム・選手"]] : []),
  ];
}
/* PC用サイドバー（大会に紐づく画面ならどこからでも呼べる・activeKeyは選択中のタブ名か"settings"） */
function tournamentSidebar(activeKey){
  const t = state.t, f = FORMATS[t.format], cfg = cfgOf(t);
  const tabs = tournamentTabs(t, cfg);
  return `<aside class="tsidebar noprint">
    <button class="tsb-back" onclick="go('home')">‹ 大会一覧へ</button>
    <div class="tsb-head">${TROPHY}<div><b>${esc(t.name)}</b><small>${esc(SPORTS[t.sport]?.label||"")}・${esc(f.label)}${cfg.host?"・"+esc(cfg.host):""}</small></div></div>
    <nav>${tabs.map(([k,l])=>
      `<button class="${activeKey===k?"on":""}" onclick="setTab('${k}')">${esc(l)}</button>`).join("")}</nav>
    <div class="tsb-foot">
      ${canEdit() ? `<button class="linkbtn${activeKey==="settings"?" on":""}" onclick="go('settings')">⚙ 大会の設定</button>` : ""}
      <button class="linkbtn" onclick="window.print()">🖨 印刷・PDF</button>
      <button class="linkbtn" onclick="shareTournament()">🔗 共有</button>
      <button class="linkbtn" onclick="refresh()">↻ 更新</button>
    </div>
  </aside>`;
}
function viewTournament(){
  const t = state.t;
  if(!t) return topbar({title:"大会", back:"go('home')"}) + `<div class="empty">読み込み中…</div>`;
  const f = FORMATS[t.format];
  const cfg = cfgOf(t);
  const tabs = tournamentTabs(t, cfg);
  // 保護者・一般が管理タブのURL状態で来ても、日程にフォールバックする
  const ADMIN_TABS = ["cards","team"];
  if(!canEdit() && ADMIN_TABS.includes(state.tab)) state.tab = "schedule";
  const body = {
    overview:tabOverview, notice:tabNotice, schedule:tabSchedule, table:tabTable, matrix:tabMatrix,
    bracket:tabBracket, scorers:tabScorers, assists:tabAssists, cards:tabCards, appear:tabAppearances, team:tabTeam,
  }[state.tab] || tabSchedule;

  return `<div class="tourwrap">`
  + topbar({ title:t.name, sub:`${SPORTS[t.sport]?.label||""}・${f.label}${cfg.host?"・"+cfg.host:""}`,
      back:"go('home')",
      act: canEdit() ? `<button class="act" onclick="go('settings')">設定</button>`
                     : `<button class="act" onclick="shareTournament()">共有</button>` })
  + `<div class="twrap">${tournamentSidebar(state.tab)}<div class="tmain">
    <div class="tabs">${tabs.map(([k,l])=>
      `<button class="${state.tab===k?"on":""}" onclick="setTab('${k}')">${esc(l)}</button>`).join("")}</div>
    <div class="screen">${body()}
      <div class="btnrow noprint">
        <button class="btn ghost sm" style="flex:1" onclick="window.print()">🖨 印刷・PDF</button>
        <button class="btn ghost sm" style="flex:1" onclick="shareTournament()">🔗 共有</button>
        <button class="btn ghost sm" style="flex:1" onclick="refresh()">↻ 更新</button>
      </div>
    </div>
  </div></div></div>`;
}
function setTab(k){ state.tab=k; state.view="t"; render(); }

/* 試合を「試合順」に並べる（キックオフ→ステージ→並び順） */
function matchesInOrder(){
  return state.matches.slice().sort((a,b)=>{
    if(a.kickoff && b.kickoff && a.kickoff!==b.kickoff) return a.kickoff.localeCompare(b.kickoff);
    if(a.kickoff && !b.kickoff) return -1;
    if(!a.kickoff && b.kickoff) return 1;
    if(a.stage!==b.stage) return a.stage==="league" ? -1 : 1;
    if(a.stage==="ko"){                                    // 櫓が複数あるときは櫓ごとにまとめる
      const ids = bracketsOf(state.t).map(x=>x.id);
      const ia = ids.indexOf(bracketIdOf(a)), ib = ids.indexOf(bracketIdOf(b));
      if(ia!==ib) return ia-ib;
    }
    return (a.sort_order||0)-(b.sort_order||0);
  });
}

/* --- ブロック（カテゴリー）切り替え。複数リーグ/複数ブロックがあるときだけ出す。空文字="すべて" ---
   得点/アシスト/警告退場/出場記録/日程タブで共通して使う（state.blockFilterを共有）。 */
function blockSwitcher(){
  const blocks = blocksOf(state.t);
  if(blocks.length<=1) return "";
  const cur = curBlockFilter();
  const tabs = [`<button class="${cur===""?"on":""}" onclick="state.blockFilter='';render()">すべて</button>`]
    .concat(blocks.map(b=>`<button class="${b.id===cur?"on":""}" onclick="state.blockFilter='${b.id}';render()">${esc(b.name)}</button>`));
  return `<div class="seg noprint" style="margin-bottom:10px;flex-wrap:wrap">${tabs.join("")}</div>`;
}
function curBlockFilter(){
  const blocks = blocksOf(state.t);
  if(blocks.length<=1) return "";
  return (state.blockFilter && blocks.some(b=>b.id===state.blockFilter)) ? state.blockFilter : "";
}

/* --- 日程・結果 --- */
/* 節・回戦ごとにグループ化する（tabSchedule表示にも、開くべき節を決める初期化にも使う共通ロジック） */
function scheduleGroups(ms){
  const multiKo = bracketsOf(state.t).length > 1;   // 櫓が複数あるときは「2位T 準決勝」のように出す
  const groups = [];
  const idxOf = {};
  ms.forEach(m=>{
    const bn = blockName(state.t, m.grp);
    const isLeague = m.stage==="league";
    const key = isLeague ? (bn ? `${bn} 第${m.round}節` : `第${m.round}節`)
              : (multiKo ? `${bracketName(state.t, bracketIdOf(m))} ${koRoundLabel(m)}` : koRoundLabel(m));
    if(!(key in idxOf)){ idxOf[key] = groups.length; groups.push({ key, matches:[], blockId: isLeague?m.grp:null }); }
    groups[idxOf[key]].matches.push(m);
  });
  groups.forEach(g=>{
    g.dateRange = null;
    if(g.matches.length && g.matches.every(m=>m.kickoff)){
      const days = g.matches.map(m=>localDate(m.kickoff)).sort();
      g.dateRange = [days[0], days[days.length-1]];
    }
  });
  return groups;
}
function scheduleDateLabel(g){
  if(!g.dateRange) return "";
  const [d0,d1] = g.dateRange;
  return d0===d1 ? fmtDate(d0) : `${fmtDate(d0)}〜${fmtDate(d1)}`;
}
/* 大会を開いたときに呼ぶ：全部たたんだ状態にしたうえで、今日にいちばん近い節/回戦だけ開き、
   その節が属するブロックを選んだ状態にする（複数リーグがあっても該当カテゴリーへ自動で行ける）。
   日付が1つも入っていない大会は開けるものが無いので、全部たたんだままにする。 */
function initScheduleCollapse(){
  state.scheduleCollapsed = {};
  state.blockFilter = "";
  const groups = scheduleGroups(matchesInOrder());
  const today = localDate(new Date().toISOString());
  const dayNum = s => Math.round(new Date(s+"T00:00:00")/86400000);
  let best = null, bestDiff = Infinity;
  groups.forEach(g=>{
    if(!g.dateRange) return;
    const [d0,d1] = g.dateRange;
    const diff = (today>=d0 && today<=d1) ? 0 : Math.min(Math.abs(dayNum(today)-dayNum(d0)), Math.abs(dayNum(today)-dayNum(d1)));
    if(diff < bestDiff){ bestDiff = diff; best = g; }
  });
  if(best){
    state.scheduleCollapsed[best.key] = false;
    if(best.blockId) state.blockFilter = best.blockId;
  }
}
/* 節・回戦ごとにグループ化して表示。グループごとに＋／－でたたんだり開いたりできる（初期状態はたたんである） */
function tabSchedule(){
  const ms = matchesInOrder();
  if(!ms.length) return `<div class="empty">試合がありません。</div>`;
  const bf = curBlockFilter();
  const shown = bf==="" ? ms : ms.filter(m=> m.stage!=="league" || m.grp===bf);
  let out = blockSwitcher();
  if(!shown.length) return out + `<div class="empty">このカテゴリーの試合はまだありません。</div>`;
  const groups = scheduleGroups(shown);
  if(canEdit()) out += `<div class="btnrow noprint" style="margin-bottom:10px">
    <button class="btn sec sm" style="flex:1" onclick="go('sched')">🗓 日程・会場をまとめて入力</button></div>`;
  groups.forEach(g=>{
    const collapsed = (state.scheduleCollapsed||{})[g.key] !== false;   // 初期値はたたんである（trueがデフォルト）
    const dLabel = scheduleDateLabel(g);
    out += `<div class="block-label-row">
      <span class="block-label" style="margin:0">${esc(g.key)}${dLabel?`　<span style="font-weight:500;color:var(--sub);font-size:12px">${esc(dLabel)}</span>`:""}</span>
      <button class="link-more noprint" onclick="toggleScheduleGroup('${esc(g.key).replace(/'/g,"\\'")}')">${collapsed?"＋ 開く":"− たたむ"}</button>
    </div>`;
    if(!collapsed) g.matches.forEach(m=> out += matchCard(m));
  });
  return out;
}
function toggleScheduleGroup(key){
  state.scheduleCollapsed = state.scheduleCollapsed || {};
  const wasCollapsed = state.scheduleCollapsed[key] !== false;
  state.scheduleCollapsed[key] = !wasCollapsed ? true : false;
  render();
}

function koRoundNames(){ return (cfgOf(state.t).overview||{}).roundNames || {}; }
function koMaxRound(bid){
  const ko = koMatchesOf(bid);
  return ko.length ? Math.max(...ko.map(m=>m.round)) : Math.round(Math.log2(cfgOf(state.t).koSize||2));
}
function koMatchNo(m){   // 同回戦内の通し番号（1始まり）
  const ms = koMatchesOf(bracketIdOf(m)).filter(x=>x.round===m.round).sort((a,b)=>a.slot-b.slot);
  return ms.findIndex(x=>x.id===m.id)+1;
}
function koRoundLabel(m){
  if(m.slot===99) return "3位決定戦";
  const bid = bracketIdOf(m);
  const names = koRoundNames();                 // 本部が自由に付けた回戦名を優先
  if(names[`${bid}:${m.round}`]) return names[`${bid}:${m.round}`];
  if(bid===KO_MAIN && names[m.round]) return names[m.round];   // 旧データ（櫓1つのころ）
  const left = koMaxRound(bid) - m.round;        // 実際の最大回戦から算出
  return ["決勝","準決勝","準々決勝"][left] || `${m.round}回戦`;   // 不戦勝はシードとして1回戦の枠に出る
}
function shortName(m){ return koRoundLabel(m) + koMatchNo(m); }

/* チーム名をタップで公開のチーム詳細ページへ（枠が空・未確定のときはリンクにしない） */
function teamNameLink(R){
  if(!R.id || R.label==="—") return `<span class="tname">${esc(R.label)}</span>`;
  return `<span class="tname" style="cursor:pointer;text-decoration:underline dotted" onclick="event.stopPropagation();openTeamPublic('${R.id}')">${esc(R.label)}</span>`;
}
function openTeamPublic(id){
  state.publicTeamId = id;
  state.view = "teamPublic";
  render();
}
function viewTeamPublic(){
  const t = (state.teams||[]).find(x=>x.id===state.publicTeamId);
  if(!t) return topbar({title:"チーム", back:"go('t')"}) + `<div class="empty">見つかりません。</div>`;
  const players = (t.players||[]).slice().sort((a,b)=>(a.no??999)-(b.no??999));
  const hasGrade = players.some(p=>p.grade);
  const staffLines = [
    t.rep_name?`代表者：${esc(t.rep_name)}`:"",
    t.coach_name?`監督：${esc(t.coach_name)}`:"",
    t.coach2_name?`コーチ：${esc(t.coach2_name)}`:"",
    t.uniform_color?`ユニフォーム：${esc(t.uniform_color)}`:"",
  ].filter(Boolean);
  return `<div class="tourwrap">`
  + topbar({ title:t.name, sub:state.t?.name||"", back:"go('t')" })
  + `<div class="screen">
    <div class="card" style="display:flex;gap:14px;align-items:center">
      ${t.crest?`<img src="${t.crest}" alt="" style="width:64px;height:64px;object-fit:contain;border-radius:10px;background:#fff;border:1px solid var(--line);flex:0 0 auto">`:""}
      <div style="min-width:0">
        <div style="font-weight:700;font-size:18px">${esc(t.name)}</div>
        ${t.short_name||t.kana?`<div class="hint" style="margin:2px 0 0">${[t.short_name,t.kana?`（${t.kana}）`:""].filter(Boolean).map(esc).join("")}</div>`:""}
      </div>
    </div>
    ${staffLines.length?`<div class="card">${staffLines.map(l=>`<div>${l}</div>`).join("")}</div>`:""}
    ${t.intro?`<div class="card"><div class="block-label" style="margin:0 0 6px">チーム紹介</div><div style="white-space:pre-wrap">${esc(t.intro)}</div></div>`:""}
    ${t.links?`<div class="card"><div class="block-label" style="margin:0 0 6px">公式サイト・SNS</div><div style="white-space:pre-wrap">${esc(t.links)}</div></div>`:""}
    <div class="block-label">選手（${players.length}名）</div>
    ${players.length ? `<div class="tblwrap"><table class="rostertbl">
      <thead><tr><th style="width:52px">番号</th><th style="text-align:left">氏名</th><th style="width:70px">位置</th>${hasGrade?`<th style="width:70px">学年</th>`:""}</tr></thead>
      <tbody>${players.map(p=>`<tr>
        <td style="text-align:center">${p.no??""}</td>
        <td style="text-align:left;padding:6px 3px">${esc(p.name||"")}</td>
        <td style="text-align:center">${esc(p.pos||"")}</td>
        ${hasGrade?`<td style="text-align:center">${p.grade?esc(String(p.grade))+"年":""}</td>`:""}
      </tr>`).join("")}</tbody></table></div>`
    : `<div class="empty">選手情報がありません。</div>`}
  </div></div>`;
}
function matchCard(m){
  const sp = sportOf(state.t);
  const H = resolveSlot(m,"H"), A = resolveSlot(m,"A");
  const w = winnerOf(m);
  const st = m.status==="live" ? `<span class="badge live">試合中</span>`
           : isDone(m)         ? `<span class="badge done">終了</span>`
           : `<span class="badge todo">未実施</span>`;
  const sc = isDone(m)
    ? `<span class="${w&&w===H.id?"win":""}">${m.home_score}</span> - <span class="${w&&w===A.id?"win":""}">${m.away_score}</span>`
    : m.status==="live" ? `${m.home_score??0} - ${m.away_score??0}` : "vs";
  const pk = (m.home_pk!=null&&m.away_pk!=null) ? `<div class="pk">PK ${m.home_pk}-${m.away_pk}</div>` : "";
  const goals = (m.events||[]).filter(e=>e.type==="goal"||e.type==="pk"||e.type==="og");
  const scline = goals.length ? `<div class="scorers">⚽ ${goals.map(e=>{
      const tid = e.team==="H" ? H.id : A.id;
      const nm = e.playerId ? playerName(tid, e.playerId) : "得点";
      return esc(nm) + (e.type==="og"?"(OG)":e.type==="pk"?"(PK)":"") + (e.minute!=null?` ${minuteText(e.minute,e.period,m)}'`:"");
    }).join("、")}</div>` : "";

  return `<div class="mcard ${canEdit()?"editable":""}">
    <div class="mhead">
      <span>${m.matchNo?`<b class="mno">No.${m.matchNo}</b> `:""}${[fmtDate(m.kickoff), fmtTime(m.kickoff), m.venue].filter(Boolean).map(esc).join(" ")||"日時未定"}</span>
      ${st}
    </div>
    <${canEdit()?`button class="mbody" onclick="openMatch('${m.id}')"`:`div class="mbody"`}>
      <span class="side">${teamNameLink(H)}</span>
      <span class="sc ${isDone(m)||m.status==="live"?"":"pending"}">${sc}${pk}</span>
      <span class="side away">${teamNameLink(A)}</span>
    </${canEdit()?"button":"div"}>
    ${m.note?`<div class="mnote">📣 ${esc(m.note)}</div>`:""}
    ${scline}
    ${canEdit() ? (m.official&&m.official.public
      ? `<div class="mpub"><span class="pill ok">🔗 公式記録を公開中</span>
          <button class="linkbtn" onclick="goOfficialPublic('${m.id}')">見る</button>
          <button class="linkbtn" onclick="copyText('${officialLinkFor(m.id)}','リンクをコピーしました')">リンクをコピー</button>
          <button class="linkbtn" style="color:var(--bad)" onclick="toggleMatchPublic('${m.id}')">非公開にする</button></div>`
      : `<div class="mpub"><button class="linkbtn" onclick="toggleMatchPublic('${m.id}')">🔗 公式記録を公開する</button></div>`)
    : (m.official&&m.official.public
      ? `<div class="mpub"><button class="linkbtn" onclick="goOfficialPublic('${m.id}')">📄 公式記録を見る</button></div>` : "")}
  </div>`;
}
function goOfficialPublic(id){ location.hash = "om=" + id; }

/* ==========================================================================
   日程・会場のまとめ入力（F1）＋ 試合番号（B1）
   ========================================================================== */
const localDate = iso=>{ if(!iso) return ""; const d=new Date(iso); return isNaN(d)?"":`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,"0")}-${String(d.getDate()).padStart(2,"0")}`; };
const localTime = iso=>{ if(!iso) return ""; const d=new Date(iso); return isNaN(d)?"":`${String(d.getHours()).padStart(2,"0")}:${String(d.getMinutes()).padStart(2,"0")}`; };
function matchStageLabel(m){
  if(m.stage==="league"){ const bn=blockName(state.t,m.grp); return bn?`${bn} リーグ`:"リーグ戦"; }
  return koRoundLabel(m);
}

